create or replace function private.service_titan_customer_intelligence(p_customer_id text) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v_result jsonb; begin if not public.has_permission_for_current_user('view_customers') then raise exception 'Customer permission required'; end if; select jsonb_build_object('memberships',coalesce((select jsonb_agg(r.payload order by nullif(r.payload->>'from','') desc nulls last) from public.service_titan_records r where r.resource='memberships' and r.payload->>'customerId'=p_customer_id),'[]'::jsonb),'payments',coalesce((select jsonb_agg(r.payload order by nullif(r.payload->>'date','') desc nulls last) from public.service_titan_records r where r.resource='payments' and coalesce(r.payload->'customer'->>'id',r.payload->>'customerId')=p_customer_id),'[]'::jsonb),'firstJobAt',(select min(coalesce(nullif(r.payload->>'createdOn','')::timestamptz,nullif(r.payload->>'completedOn','')::timestamptz)) from public.service_titan_records r where r.resource='jobs' and r.payload->>'customerId'=p_customer_id),'lastJobAt',(select max(coalesce(nullif(r.payload->>'completedOn','')::timestamptz,nullif(r.payload->>'createdOn','')::timestamptz)) from public.service_titan_records r where r.resource='jobs' and r.payload->>'customerId'=p_customer_id),'completedJobs',(select count(*) from public.service_titan_records r where r.resource='jobs' and r.payload->>'customerId'=p_customer_id and lower(coalesce(r.payload->>'jobStatus',''))='completed'),'collectedRevenue',coalesce((select sum(case when coalesce(r.payload->>'total','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (r.payload->>'total')::numeric else 0 end) from public.service_titan_records r where r.resource='payments' and coalesce(r.payload->'customer'->>'id',r.payload->>'customerId')=p_customer_id),0)); return v_result; end $$;
create or replace function public.service_titan_customer_intelligence(p_customer_id text) returns jsonb language sql stable set search_path='' as $$ select private.service_titan_customer_intelligence(p_customer_id) $$; revoke all on function public.service_titan_customer_intelligence(text) from public,anon; grant execute on function public.service_titan_customer_intelligence(text) to authenticated;
create or replace function private.service_titan_dispatch_feed(p_start timestamptz,p_end timestamptz) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v_result jsonb; begin if not public.has_permission_for_current_user('view_dispatch') then raise exception 'Dispatch permission required'; end if; select coalesce(jsonb_agg(x order by x->>'start'),'[]'::jsonb) into v_result from (select jsonb_build_object('appointment',a.payload,'job',j.payload,'customer',c.payload,'location',l.payload) x from public.service_titan_records a left join public.service_titan_records j on j.resource='jobs' and j.external_id=a.payload->>'jobId' left join public.service_titan_records c on c.resource='customers' and c.external_id=coalesce(a.payload->>'customerId',j.payload->>'customerId') left join public.service_titan_records l on l.resource='locations' and l.external_id=j.payload->>'locationId' where a.resource='appointments' and nullif(a.payload->>'start','')::timestamptz>=p_start and nullif(a.payload->>'start','')::timestamptz<p_end order by nullif(a.payload->>'start','')::timestamptz) q; return v_result; end $$;
create or replace function public.service_titan_dispatch_feed(p_start timestamptz,p_end timestamptz) returns jsonb language sql stable set search_path='' as $$ select private.service_titan_dispatch_feed(p_start,p_end) $$; revoke all on function public.service_titan_dispatch_feed(timestamptz,timestamptz) from public,anon; grant execute on function public.service_titan_dispatch_feed(timestamptz,timestamptz) to authenticated;
create or replace function private.service_titan_technician_directory() returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v jsonb; begin if not public.has_permission_for_current_user('view_dispatch') then raise exception 'Dispatch permission required'; end if; select coalesce(jsonb_agg(payload order by lower(payload->>'name')),'[]'::jsonb) into v from public.service_titan_records where resource='technicians' and coalesce((payload->>'active')::boolean,true); return v; end $$;
create or replace function public.service_titan_technician_directory() returns jsonb language sql stable set search_path='' as $$ select private.service_titan_technician_directory() $$; revoke all on function public.service_titan_technician_directory() from public,anon; grant execute on function public.service_titan_technician_directory() to authenticated;